<?= $this->extend('layout') ?><?= $this->section('content') ?><section class="card"><h1><?= empty($product['id'])?'Add Product':'Edit Product' ?></h1><form method="post" enctype="multipart/form-data" action="<?= empty($product['id'])?site_url('products'):site_url('products/'.$product['id']) ?>"><?= csrf_field() ?><label for="name">Product name</label><input id="name" name="name" maxlength="100" required value="<?= esc(old('name',$product['name']??'')) ?>"><label for="price">Price</label><input id="price" type="number" name="price" step="0.01" min="0" required value="<?= esc(old('price',$product['price']??'')) ?>"><label for="stock_quantity">Stock quantity</label><input id="stock_quantity" type="number" name="stock_quantity" min="0" required value="<?= esc(old('stock_quantity',$product['stock_quantity']??'0')) ?>"><label for="image">Product image</label><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>Optional JPG, PNG, or WebP image, maximum 3 MB. It will be prepared as a display image.</small><p><button>Save Product</button> <a href="<?= site_url('products') ?>">Cancel</a></p></form></section><?= $this->endSection() ?>
